function crumbEl(parts){
  return '<div class="crumb" style="margin-bottom:14px;">' + parts.map(function(p, i){
    var last = i === parts.length - 1;
    return (i > 0 ? '<span class="sep">/</span>' : '') +
      '<span class="seg ' + (last ? 'current' : '') + '" ' + (p.nav ? ('data-nav="' + escapeHtml(p.nav) + '" style="cursor:pointer;"') : '') + '>' +
      escapeHtml(p.label) + '</span>';
  }).join('') + '</div>';
}
window.crumbEl = crumbEl;

