// Хранилище строки поиска справочника
if(typeof EL !== 'undefined'){
  EL.refSearch = '';
}

function elRef(){
  var searchVal = (typeof EL !== 'undefined' && EL.refSearch) ? EL.refSearch.toLowerCase().trim() : '';

  var groups = [
    { name: 'Боевая система и Правила', color: '#ef4444', icon: '⚔️' },
    { name: 'Магия Стихий и Искусства', color: '#38bdf8', icon: '🌀' },
    { name: 'Народы и География', color: '#10b981', icon: '🌏' },
    { name: 'Общество, Социум и Закон', color: '#f59e0b', icon: '🏛️' },
    { name: 'Духовный мир и Верования', color: '#a855f7', icon: '✨' }
  ];

  var html = crumbEl([{ label: 'Стихия', nav: 'home' }, { label: 'Справочник' }]) +
    '<button class="back" data-nav="home">← На главную</button>' +
    '<div class="el-hud" style="margin-top:10px;">' +
      '<div style="font-size:26px;font-weight:800;color:#fff;letter-spacing:0.02em;font-family:Cinzel,serif;margin-bottom:4px;">📚 Справочник</div>' +
      '<div style="font-size:14px;color:#94a3b8;font-style:italic;font-family:EB Garamond,serif;">Тактический свод правил, боевой механики, магии четырёх народов, обычаев и законов мира.</div>' +
    '</div>' +
    '<div class="el-ref-search-wrap">' +
      '<span class="el-ref-search-icon">🔍</span>' +
      '<input type="text" id="elRefSearch" class="el-ref-search-input" placeholder="Поиск по справочнику (урон стихий, выносливость, окна, металл, молния, ба синг се...)" value="' + escapeHtml(searchVal) + '">' +
    '</div>';

  var totalFound = 0;

  groups.forEach(function(grp){
    var itemsInGroup = EL_REF_DATA.filter(function(it){
      if(it.group !== grp.name) return false;
      if(!searchVal) return true;
      var haystack = (it.t + ' ' + it.d + ' ' + (it.tag || '') + ' ' + (it.summary || '')).toLowerCase();
      return haystack.indexOf(searchVal) !== -1;
    });

    if(itemsInGroup.length === 0) return;
    totalFound += itemsInGroup.length;

    html += '<div class="el-ref-group-block">' +
      '<div class="el-ref-group-title" style="border-left-color:' + grp.color + ';">' +
        '<span>' + grp.icon + ' ' + escapeHtml(grp.name) + '</span>' +
        '<span class="el-ref-group-count">' + itemsInGroup.length + '</span>' +
      '</div>' +
      '<div class="menu-list grid-2">' +
        itemsInGroup.map(function(it){
          return '<div class="el-ref-card" data-nav="elRefView:' + it.id + '">' +
            '<div style="flex:1;min-width:0;">' +
              '<div class="name">' +
                it.icon + ' ' + escapeHtml(it.t) +
                (it.tag ? '<span class="el-ref-item-tag">' + escapeHtml(it.tag) + '</span>' : '') +
              '</div>' +
              '<div class="desc">' + escapeHtml(it.d) + '</div>' +
            '</div>' +
            '<div class="arrow">›</div>' +
          '</div>';
        }).join('') +
      '</div>' +
    '</div>';
  });

  if(totalFound === 0 && searchVal){
    html += '<div class="char-empty" style="margin-top:24px;text-align:center;padding:30px;background:var(--el-card-bg);border:1px solid var(--el-accent-border);border-radius:6px;color:#94a3b8;">По запросу «' + escapeHtml(searchVal) + '» ничего не найдено. Попробуйте другой термин.</div>';
  }

  return html;
}
window.elRef = elRef;

function elRefView(key){
  var art = null;
  for(var i = 0; i < EL_REF_DATA.length; i++){
    if(EL_REF_DATA[i].id === key){
      art = EL_REF_DATA[i];
      break;
    }
  }

  if(!art){
    return crumbEl([{ label: 'Стихия', nav: 'home' }, { label: 'Справочник', nav: 'elRef' }, { label: 'Не найдено' }]) +
      '<button class="back" data-nav="elRef">← Назад в Справочник</button>' +
      '<div class="char-empty" style="margin-top:20px;text-align:center;">Статья не найдена.</div>';
  }

  var html = crumbEl([{ label: 'Стихия', nav: 'home' }, { label: 'Справочник', nav: 'elRef' }, { label: art.t }]) +
    '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:14px;flex-wrap:wrap;gap:10px;">' +
      '<button class="back" data-nav="elRef" style="margin-bottom:0;">← Назад в Справочник</button>' +
      '<button class="el-ref-copy-btn" id="elCopyRefBtn" data-prompt="' + escapeHtml(art.dmPrompt || '') + '">📋 Скопировать для AI-Мастера</button>' +
    '</div>' +
    '<div class="el-ref-detail-header">' +
      '<div style="display:flex;gap:8px;align-items:center;margin-bottom:8px;flex-wrap:wrap;">' +
        '<span class="el-ref-item-tag">' + escapeHtml(art.group) + '</span>' +
        (art.tag ? '<span class="el-ref-item-tag" style="background:rgba(255,255,255,0.06);color:#cbd5e1;border-color:rgba(255,255,255,0.15);">' + escapeHtml(art.tag) + '</span>' : '') +
      '</div>' +
      '<h1 style="font-size:24px;font-weight:800;color:#fff;margin:0 0 6px 0;font-family:Cinzel,serif;">' + art.icon + ' ' + escapeHtml(art.t) + '</h1>' +
      '<div style="font-size:14px;color:#94a3b8;font-style:italic;font-family:EB Garamond,serif;line-height:1.5;">' + escapeHtml(art.summary || art.d) + '</div>' +
    '</div>';

  if(art.sections && art.sections.length > 0){
    art.sections.forEach(function(sec){
      html += '<div class="el-ref-section-card">' +
        '<div class="el-ref-section-title">' + escapeHtml(sec.title) + '</div>' +
        '<div style="font-size:13.5px;color:#cbd5e1;line-height:1.65;">' + sec.content + '</div>' +
      '</div>';
    });
  }

  html += '<div style="margin-top:24px;text-align:center;">' +
    '<button class="back" data-nav="elRef" style="display:inline-block;">← Вернуться ко всем статьям Справочника</button>' +
  '</div>';

  return html;
}
window.elRefView = elRefView;

function wireElRef(){
  var searchInput = document.getElementById('elRefSearch');
  if(searchInput){
    searchInput.focus();
    // restore cursor to end
    var len = searchInput.value.length;
    searchInput.setSelectionRange(len, len);

    searchInput.addEventListener('input', function(){
      if(typeof EL !== 'undefined'){
        EL.refSearch = searchInput.value;
      }
      var app = document.getElementById('app');
      if(app){
        app.innerHTML = elRef();
        if(typeof wireEvents === 'function') wireEvents();
        wireElRef();
      }
    });
  }
}
window.wireElRef = wireElRef;

function wireElRefView(){
  var copyBtn = document.getElementById('elCopyRefBtn');
  if(copyBtn){
    copyBtn.onclick = function(){
      var promptText = copyBtn.getAttribute('data-prompt');
      if(promptText && typeof copyText === 'function'){
        copyText(promptText);
        copyBtn.textContent = 'Скопировано ✓';
        setTimeout(function(){
          copyBtn.textContent = '📋 Скопировать для AI-Мастера';
        }, 1500);
      }
    };
  }
}
window.wireElRefView = wireElRefView;


