EL.getTechs = function(){
  try {
    var raw = localStorage.getItem('el_techs');
    if(raw){
      var list = JSON.parse(raw);
      var prewrittenTechIds = [
        'tech_fire_daggers', 'tech_fire_lightning', 'tech_fire_jet', 'tech_fire_combustion',
        'tech_earth_armor', 'tech_earth_seismic', 'tech_earth_metal_whip', 'tech_earth_lava',
        'tech_water_whip', 'tech_water_heal', 'tech_water_blood', 'tech_water_ice_spikes',
        'tech_air_blast', 'tech_air_scooter', 'tech_air_asphyxiation', 'tech_air_flight',
        'tech_dark_shadow_step', 'tech_dark_void_grasp'
      ];
      var cleaned = list.filter(function(t){ return prewrittenTechIds.indexOf(t.id) === -1; });
      if(cleaned.length !== list.length){
        localStorage.setItem('el_techs', JSON.stringify(cleaned));
      }
      return cleaned;
    }
  } catch(e){}
  return [];
};

EL.saveTechs = function(techs){
  try {
    localStorage.setItem('el_techs', JSON.stringify(techs));
  } catch(e){}
};

// Управление хранилищем приёмов
EL.getMoves = function(){
  try {
    var raw = localStorage.getItem('el_moves');
    if(raw){
      var list = JSON.parse(raw);
      var prewrittenMoveIds = [
        'move_dust', 'move_sweep', 'move_disarm', 'move_chiblock', 'move_step',
        'move_iron_shoulder', 'move_headbutt', 'move_joint_lock', 'move_vault', 'move_kyoshi_fan'
      ];
      var cleaned = list.filter(function(m){ return prewrittenMoveIds.indexOf(m.id) === -1; });
      if(cleaned.length !== list.length){
        localStorage.setItem('el_moves', JSON.stringify(cleaned));
      }
      return cleaned;
    }
  } catch(e){}
  return [];
};

EL.saveMoves = function(moves){
  try {
    localStorage.setItem('el_moves', JSON.stringify(moves));
  } catch(e){}
};

// Состояние карты мира
EL.getMapState = function(){
  try {
    var raw = localStorage.getItem('el_map_state');
    if(raw) return JSON.parse(raw);
  } catch(e){}
  return {
    selectedId: 'republic_city',
    filter: 'all',
    routeFrom: 'republic_city',
    routeTo: 'ba_sing_se',
    transport: 'bison'
  };
};

EL.saveMapState = function(st){
  try {
    localStorage.setItem('el_map_state', JSON.stringify(st));
  } catch(e){}
};

// Вспомогательные функции экранирования
function elEsc(s){
  return String(s == null ? '' : s)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}
function elEscA(s){
  return String(s == null ? '' : s)
    .replace(/&/g, '&amp;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

function elScaleStars(sc){
  var n = Math.max(0, Math.min(5, parseInt(sc, 10) || 0));
  var stars = '';
  for(var i=1; i<=5; i++){
    stars += (i <= n) ? '★' : '☆';
  }
  return '<span style="color:#f59e0b;letter-spacing:1px;font-weight:700;" title="Шкала ' + n + ' из 5">' + stars + '</span>' +
         '<span style="font-size:11px;color:#94a3b8;margin-left:4px;">(Шкала ' + n + ')</span>';
}

function elElemClass(elem){
  if(elem === 'Огонь') return 'elem-fire';
  if(elem === 'Вода') return 'elem-water';
  if(elem === 'Земля') return 'elem-earth';
  if(elem === 'Тьма') return 'elem-dark';
  return 'elem-wind';
}

function elKindClass(kind){
  if(kind === 'Чи-блокинг') return 'kind-chi';
  if(kind === 'Оружейный') return 'kind-weapon';
  if(kind === 'Тактический') return 'kind-tactical';
  return 'kind-melee';
}

