window._elTechSearch = window._elTechSearch || '';
window._elTechElemFilter = window._elTechElemFilter || 'all';

function renderElTechCard(t){
  var elemIcon = t.element === 'Огонь' ? '🔥' : t.element === 'Вода' ? '🌊' : t.element === 'Земля' ? '⛰️' : t.element === 'Тьма' ? '🌑' : '🌪️';
  var benefitText = t.benefit === 'cheap' ? '✦ Снижение стоимости (-1 МВН)' : '✦ Преимущество на бросок атаки';
  var winBadge = (t.reqWindow && t.reqWindow !== 'нет')
    ? '<span class="el-mini-tag tag-win">🎯 Окно: ' + elEsc(t.reqWindow) + '</span>'
    : '';

  return '<div class="el-tech-card ' + elElemClass(t.element) + '" data-nav="elTechView:' + elEscA(t.id) + '">' +
    '<div class="el-item-badges">' +
      '<span class="el-mini-tag" style="color:var(--el-accent);">' + elemIcon + ' ' + elEsc(t.element) + ' · ' + elEsc(t.subArt || 'Базовое') + '</span>' +
      '<span class="el-mini-tag tag-cost">⚡ ' + elEsc(t.cost || '1 МВН') + '</span>' +
      '<span class="el-mini-tag tag-benefit">' + benefitText + '</span>' +
      winBadge +
      '<span style="margin-left:auto;">' + elScaleStars(t.scale) + '</span>' +
    '</div>' +
    '<div class="el-item-name">' + elEsc(t.name) + '</div>' +
    '<div class="el-item-line">Дистанция: <b style="color:#fff;">' + elEsc(t.range || 'Ближний бой') + '</b> · Эффект/Урон: <b style="color:var(--el-accent);">' + elEsc(t.damage || '—') + '</b></div>' +
    '<div class="el-item-desc">' + elEsc(t.desc || '') + '</div>' +
  '</div>';
}
window.renderElTechCard = renderElTechCard;



