function elTechView(id){
  var techs = EL.getTechs();
  var t = techs.filter(function(x){ return x.id === id; })[0];
  if(!t) return elTechs();

  var elemIcon = t.element === 'Огонь' ? '🔥' : t.element === 'Вода' ? '🌊' : t.element === 'Земля' ? '⛰️' : t.element === 'Тьма' ? '🌑' : '🌪️';
  var benefitText = t.benefit === 'cheap' ? 'Снижение стоимости (-1 МВН)' : 'Преимущество на бросок атаки';

  var rows = [
    { k: 'Стихия', v: elemIcon + ' ' + t.element },
    { k: 'Высшее искусство', v: t.subArt || 'Базовое применение' },
    { k: 'Шкала мастерства (0–5)', v: elScaleStars(t.scale), raw: true },
    { k: 'Стоимость применения', v: '<b style="color:#fca5a5;">' + elEsc(t.cost) + '</b>', raw: true },
    { k: 'Бонус выученной формы', v: '<b style="color:#7dd3fc;">' + benefitText + '</b>', raw: true },
    { k: 'Требуемое окно (A94)', v: (t.reqWindow && t.reqWindow !== 'нет') ? '<span class="el-mini-tag tag-win">🎯 ' + elEsc(t.reqWindow) + '</span>' : 'Не требуется (любая ситуация)', raw: true },
    { k: 'Дистанция / Зона', v: elEsc(t.range || 'Ближний бой') },
    { k: 'Урон / Эффект', v: '<b style="color:var(--el-accent);">' + elEsc(t.damage || '—') + '</b>', raw: true },
    { k: 'Описание и пластика', v: elEsc(t.desc || '—') }
  ];

  var tableHtml = rows.map(function(r){
    return '<div class="hb-row" style="display:flex;padding:10px 14px;border-bottom:1px solid rgba(255,255,255,0.06);align-items:flex-start;">' +
      '<div class="hb-row-k" style="width:200px;flex-shrink:0;font-size:12px;color:#94a3b8;font-family:JetBrains Mono,monospace;font-weight:700;">' + elEsc(r.k) + '</div>' +
      '<div class="hb-row-v" style="flex:1;font-size:13.5px;color:#e2e8f0;">' + (r.raw ? r.v : elEsc(r.v)) + '</div>' +
    '</div>';
  }).join('');

  return crumbEl([{label:'Стихия', nav:'home'}, {label:'Формы', nav:'elTechs'}, {label: t.name}]) +
    '<button class="back" data-nav="elTechs">← К списку форм</button>' +
    '<h1>' + elemIcon + ' ' + elEsc(t.name) + '</h1>' +
    '<div class="subtitle">' + elEsc(t.element) + ' • ШКАЛА ' + (t.scale || 0) + ' • ' + elEsc(t.subArt || 'Базовое') + '</div>' +
    '<div class="el-loc-dossier" style="margin-top:16px;padding:0;overflow:hidden;">' +
      tableHtml +
    '</div>' +
    '<div class="el-ref-callout" style="margin-top:14px;background:rgba(0,0,0,0.35);border:1px solid var(--el-accent-border);border-left:4px solid var(--el-accent);padding:12px 16px;border-radius:4px;font-size:13px;color:#cbd5e1;line-height:1.5;">' +
      'ℹ️ <b>Механика форм стихий (W4-БИС // A93)</b>: В мире Аватара формы не расходуют слоты заклинаний. Выученная форма даёт выбор перед броском: совершить атаку с <b>Преимуществом</b> либо снизить затраты на <b>-1 МВН</b> (минимум 1). Для применения разрушительных форм шкалы 3+ необходимо предварительно открыть у противника Окно возможностей (A94)!' +
    '</div>' +
    '<div class="sheet-actions" style="margin-top:18px;display:flex;gap:10px;">' +
      '<button class="btn-primary" data-nav="elTechEdit:' + elEscA(t.id) + '">✏️ Редактировать форму</button>' +
      '<button class="btn-ghost" id="elTechDeleteBtn" style="color:#fca5a5;border-color:rgba(239,68,68,0.35);">🗑️ Забыть форму</button>' +
    '</div>';
}

