function wireElTechEdit(){
  var saveBtn = document.getElementById('elTechSaveBtn');
  if(saveBtn){
    saveBtn.onclick = function(){
      var name = document.getElementById('elTechEditName').value.trim();
      if(!name){ alert('Введите название формы'); return; }
      var elem = document.getElementById('elTechEditElem').value;
      var sub = document.getElementById('elTechEditSub').value.trim() || 'Базовое';
      var scale = parseInt(document.getElementById('elTechEditScale').value, 10) || 0;
      var cost = document.getElementById('elTechEditCost').value.trim() || '1 МВН';
      var benefit = document.getElementById('elTechEditBenefit').value;
      var win = document.getElementById('elTechEditWindow').value.trim() || 'нет';
      var range = document.getElementById('elTechEditRange').value.trim() || 'Ближний бой';
      var dmg = document.getElementById('elTechEditDmg').value.trim();
      var desc = document.getElementById('elTechEditDesc').value.trim();

      var techs = EL.getTechs();
      var isNew = view.shId === 'new';
      var targetId = isNew ? ('tech_' + Date.now()) : view.shId;

      var record = {
        id: targetId,
        name: name,
        element: elem,
        subArt: sub,
        scale: scale,
        cost: cost,
        benefit: benefit,
        reqWindow: win,
        range: range,
        damage: dmg,
        desc: desc
      };

      if(isNew){
        techs.push(record);
      } else {
        techs = techs.map(function(x){ return x.id === targetId ? record : x; });
      }

      EL.saveTechs(techs);
      window.navigate('elTechView:' + targetId);
    };
  }
}

function elShowFade(el){
  if(!el) return;
  el.style.display = 'block';
  el.classList.remove('fade-zoom');
  void el.offsetWidth;
  el.classList.add('fade-zoom');
}

function callGeminiAvatarTechGenerator(opts, apiKey, callback){
  if(!apiKey){
    callback("API ключ не указан", null);
    return;
  }
  var prompt = "Ты профессиональный ведущий (Dungeon Master) и глубокий знаток вселенной Avatar: The Last Airbender и The Legend of Korra (Мир четырёх стихий: Огонь, Вода, Земля, Воздух, и подстихии). " +
    "Придумай и сбалансируй лорную форму стихии (Bending Form / Высшее искусство) для настольной ролевой игры. " +
    "КРИТИЧЕСКИ ВАЖНО: Это вселенная Аватара (магия стихий, восточные единоборства, концентрация Ци, дыхание, свитки мастеров), а НЕ Наруто! Категорически запрещено использовать: печати рук, чакру, ниндзюцу, гендзюцу, додзюцу, кланы шиноби, каге, кунаи и т.д.!\n" +
    "Пожелания игрока:\n" +
    "- Идея / Тема: " + (opts.theme || "Случайная каноничная форма стихий") + "\n" +
    "- Стихия: " + (opts.element || "Любая на усмотрение AI (Огонь, Вода, Земля, Воздух или Тьма)") + "\n" +
    "- Высшее искусство / Направление: " + (opts.subArt || "Авто (Базовое, Молния, Сейсмочувствительность, Металл, Лава, Кровь, Лёд, Исцеление, Полёт, Духовная магия)") + "\n" +
    "- Шкала мастерства (0–5): " + (opts.scale !== '' && opts.scale !== undefined ? opts.scale : "Авто") + " (Официальная сетка урона: 0 ст. = 1d4+мод, 1 ст. = 1d8+мод, 2 ст. = 2d8+мод, 3 ст. = 3d10+мод [требует Окно A94], 4 ст. = 5d10, 5 ст. = 8d10–10d10+)\n" +
    "- Бонус выученной формы: " + (opts.benefit || "Авто") + "\n\n" +
    "Ответь ИСКЛЮЧИТЕЛЬНО валидным JSON-объектом без лишних символов и markdown-разметки, со следующими полями:\n" +
    "{\n" +
    '  "name": "Атмосферное и каноничное название формы в стиле Аватара",\n' +
    '  "element": "Огонь / Вода / Земля / Воздух / Тьма",\n' +
    '  "subArt": "Базовое / Молния / Металл / Лава / Кровь / Лёд / Исцеление / Полёт / Сейсмика",\n' +
    '  "scale": 1,\n' +
    '  "cost": "1 МВН",\n' +
    '  "benefit": "advantage",\n' +
    '  "reqWindow": "нет",\n' +
    '  "range": "Дистанция (например: Ближний бой, 30 фт, 60 фт, Конус 20 фт)",\n' +
    '  "damage": "Формула урона строго по степени (например: 1d8+ХАР огненный, 2d8+ТЕЛ дробящий, 3d10+МУД колющий/холод, Исцеление 2d8+МУД)",\n' +
    '  "desc": "Детальное боевое описание: восточный стиль единоборств (Северный Шаолинь для Огня, Тайцзицюань для Воды, Хунгар для Земли, Багуачжан для Воздуха), стойка, движение тела, концентрация Ци и визуальный эффект стихии."\n' +
    "}";

  requestGeminiGenerateContent(prompt, apiKey, function(err, data){
    if(err || !data){
      callback(err ? (err.message || String(err)) : "Пустой ответ от AI", null);
      return;
    }
    try{
      var parsed = extractJsonFromAi(data);
      callback(null, parsed);
    }catch(err2){
      callback("Ошибка разбора JSON: " + err2.message, null);
    }
  });
}
