// Управление тактическими метками пользователя (localStorage)
function elLoadUserMarkers(){
  try {
    var raw = localStorage.getItem('el_user_markers');
    if(raw) return JSON.parse(raw);
  } catch(e){}
  return [];
}

function elSaveUserMarkers(markers){
  try {
    localStorage.setItem('el_user_markers', JSON.stringify(markers));
  } catch(e){}
}

function elGetMarkerById(id){
  var list = elLoadUserMarkers();
  for(var i=0; i<list.length; i++){
    if(list[i].id === id) return list[i];
  }
  return null;
}

